        {description && <p className="text-xs text-text-secondary">{description}</p>}
      </div>
      {toggle ? (
        <Switch aria-labelledby={id} checked={checked} onCheckedChange={onCheckedChange} />
      ) : (
        control
      )}
    </div>
  )
}

